// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // Fuzzed params: an address 'from' and a uint 'v' and a uint8 k to vary _tos length (kept small)
    function testFuzz_property(address from, uint256 v, uint8 n) public {
        // keep _tos length between 1 and 5 to keep fuzz wide but practical
        uint256 len = bound(n, 1, 5);

        // Deploy a helper that can be toggled to revert on call; we will use the reverting variant
        ReverterReenter helper = new ReverterReenter(address(c));

        address[] memory tos = new address[](len);
        // Put the helper address as at least one recipient; ensure at least one call will revert by making all recipients be helper
        for (uint i = 0; i < len; i++) {
            tos[i] = address(helper);
        }

        bool ok;
        // call transfer; the reference implementation should revert because helper reverts inside its fallback
        try c.transfer(from, address(helper), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertion): For ANY inputs where the callee reverts on the invoked call(s),
        // the correct contract must NOT return true (i.e., call must revert). The buggy mutant (which drops require on success)
        // can return true despite callee failures. We assert that this call did NOT succeed (ok == false).
        assertTrue(ok == false);
    }
}

// Helper that always reverts when called with the selector transferFrom(address,address,uint256).
// It is minimal and explicitly matches the selector used by C so the low-level call succeeds in dispatching here,
// and then it reverts to simulate a failing external party.
contract ReverterReenter {
    address public target;
    constructor(address _t) { target = _t; }

    // match the signature transferFrom(address,address,uint256)
    function transferFrom(address /*from*/, address /*to*/, uint256 /*v*/) external pure {
        revert("revert-from-helper");
    }

    // Fallback to revert as well for any mismatched calldata
    fallback() external payable { revert("revert-fallback"); }
}
